#!/usr/bin/env node
/**
 * Single-sources the push dispatcher's shared logic from the client source of truth:
 *
 *   src/lib/pushCore.ts  ->  supabase/functions/push-dispatch/pushCore.ts  (verbatim copy)
 *
 * The dispatcher and the app must never disagree about the notification copy, the deep
 * links, or when a subscription is due — a drifted copy would mean the server pokes at a
 * time the app never promised, or says words the app never approved. Never edit the
 * generated file directly — edit the client source and re-run:
 *
 *   npm run sync:push     regenerate
 *   npm run check:push    fail if the generated file is stale (also covered by tests)
 */
import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const checkOnly = process.argv.includes('--check');

const HEADER = `// GENERATED by scripts/sync-push-core.mjs from src/lib/pushCore.ts — do not edit by hand.
// The notification copy rule and the due-matching rules live in the client source so the
// tests can pin them; this copy exists so the edge function runs the identical logic.
`;

const source = readFileSync(join(root, 'src/lib/pushCore.ts'), 'utf8');
const generated = HEADER + source;
const target = join(root, 'supabase/functions/push-dispatch/pushCore.ts');

if (checkOnly) {
  if (!existsSync(target) || readFileSync(target, 'utf8') !== generated) {
    console.error('push-dispatch/pushCore.ts is stale. Run: npm run sync:push');
    process.exit(1);
  }
  console.log('push core in sync.');
} else {
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, generated);
  console.log('wrote supabase/functions/push-dispatch/pushCore.ts');
}
